/* v5.5.132 - LinkedIn-style notification pill toasts. */
@keyframes slideDownFadIn {
    0% {
        opacity: 0;
        transform: translateY(-20px) scale(.95);
    }
    100% {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

#cv-toast-container {
    pointer-events: none;
}

.cv-toast-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    border: 0;
    border-radius: 999px;
    padding: 6px 16px;
    min-height: 34px;
    max-width: min(92vw, 560px);
    box-shadow: 0 8px 20px rgba(15, 23, 42, .12);
    color: #fff;
    background: #3b66d4;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 13px;
    font-weight: 800;
    line-height: 1.25;
    letter-spacing: .02em;
    text-align: center;
    cursor: default;
    user-select: none;
    pointer-events: auto;
    transition: opacity .25s ease, transform .25s ease, background-color .2s ease;
}

.cv-toast-pill:hover {
    background: #325ac0;
}

.cv-toast-pill svg {
    flex: 0 0 auto;
    opacity: .9;
}

.cv-toast-pill span {
    display: inline-block;
}

.cv-toast-pill--success,
.cv-toast-pill--info {
    background: #3b66d4;
}

.cv-toast-pill--success:hover,
.cv-toast-pill--info:hover {
    background: #325ac0;
}

.cv-toast-pill--error {
    background: #ef3f67;
}

.cv-toast-pill--error:hover {
    background: #dc3159;
}

.cv-toast-pill.toast-animate {
    animation: slideDownFadIn .4s cubic-bezier(.16, 1, .3, 1) forwards;
}

.cv-toast-pill.is-hiding {
    opacity: 0;
    transform: translateY(-12px) scale(.96);
}

@media (max-width: 640px) {
    .cv-toast-pill {
        max-width: calc(100vw - 24px);
        padding: 6px 14px;
        font-size: 12.5px;
    }
}


